mapper.select:
select favorite_id, user_id, goods_id, create_time
from tb_newbee_mall_goods_favorite
where user_id = #{userId} and goods_id = #{goodsId}

select favorite.goods_id, goods.goods_name, goods.goods_cover_img, goods.selling_price, goods.goods_sell_status
from tb_newbee_mall_goods_favorite favorite
left join tb_newbee_mall_goods_info goods on goods.goods_id = favorite.goods_id
where favorite.user_id = #{userId}
order by favorite.create_time desc, favorite.favorite_id desc
limit #{offset}, #{pageSize}
